// Glossary — auto-generated from transcripts
export const glossary = [
  { term: 'Backpressure', def: 'A reactive flow-control mechanism in which downstream consumers signal to upstream producers how much data they can handle, preventing a fast source from overwhelming a slow consumer.' },
  { term: 'Bidirectional Streaming', def: 'A reactive communication pattern in which a client and server exchange many messages in both directions over a single connection, unlike the single request/response of traditional Spring MVC.' },
  { term: 'BodyToFlux', def: 'A WebClient method that deserializes a response body into a Flux, used when the downstream service emits a stream or collection of items rather than a single object.' },
  { term: 'BodyToMono', def: 'A WebClient method that deserializes a response body into a Mono, used when the downstream service returns a single object.' },
  { term: 'Client-Streaming', def: 'A reactive communication pattern in which the client sends many messages and the server emits a single response, one of the four patterns supported by Spring WebFlux.' },
  { term: 'DoOnNext', def: 'A Project Reactor operator that runs a side-effect (such as logging) for each item emitted by a Flux, preserving the streaming behavior of the pipeline.' },
  { term: 'Elastic', def: 'One of the four principles of the Reactive Manifesto; a system remains responsive under varying workload by scaling resources up or down reactively.' },
  { term: 'Flux', def: 'A Project Reactor publisher type that emits zero to many items, then completes or errors; used by Spring WebFlux for multi-value reactive streams.' },
  { term: 'Functional Endpoints', def: 'A lightweight, lambda-based alternative to annotation-driven controllers in Spring WebFlux, where routes are configured programmatically rather than via @RestController.' },
  { term: 'MediaType.TEXT_EVENT_STREAM_VALUE', def: 'The constant for the text/event-stream MIME type (the Server-Sent Events media type) in Spring WebFlux, used to signal a browser to render items as they arrive instead of buffering the full response.' },
  { term: 'Message-Driven', def: 'One of the four principles of the Reactive Manifesto; reactive systems rely on asynchronous message passing between components rather than direct calls.' },
  { term: 'Mono', def: 'A Project Reactor publisher type that emits zero or one item, then completes or errors; used by Spring WebFlux for single-value reactive results.' },
  { term: 'N+1 Query Problem', def: 'A performance anti-pattern in which fetching N parent rows triggers N additional child queries (one per parent); R2DBC deliberately avoids this by omitting relationship-mapping annotations such as @OneToMany.' },
  { term: 'OnErrorComplete', def: 'A Project Reactor operator that converts an upstream onError signal into an onComplete signal, allowing partial results already emitted to be delivered cleanly to the consumer.' },
  { term: 'OnErrorResume', def: 'A Project Reactor operator that catches an upstream error and substitutes a fallback publisher, enabling declarative error recovery in a reactive pipeline.' },
  { term: 'OnErrorReturn', def: 'A Project Reactor operator that catches an upstream error and emits a single fallback value, terminating the pipeline normally.' },
  { term: 'ParameterizedTypeReference', def: 'A Spring utility that captures generic type information at runtime by subclassing, required for deserializing generic types like List<Product> because Java erases generics so List<Product>.class is illegal.' },
  { term: 'Project Reactor', def: 'The reactive library that provides the Mono and Flux publisher types and the operator vocabulary used by Spring WebFlux.' },
  { term: 'R2DBC', def: 'Reactive Relational Database Connectivity, a specification purpose-built for non-blocking access to relational databases, distinct from JPA and designed to support backpressure and streaming.' },
  { term: 'Reactive Manifesto', def: 'A document that defines the four principles of reactive systems: responsive, resilient, elastic, and message-driven — the design foundation for Spring WebFlux.' },
  { term: 'ReactiveCrudRepository', def: 'A Spring Data R2DBC base interface that provides reactive CRUD methods out of the box, with single-value methods returning Mono and multi-value methods returning Flux.' },
  { term: 'Resilient', def: 'One of the four principles of the Reactive Manifesto; a system stays responsive in the face of failure through replication, isolation, and delegated recovery.' },
  { term: 'Responsive', def: 'The anchor principle of the Reactive Manifesto; a system reacts to user input without significant delay, often by streaming partial results rather than waiting for a complete response.' },
  { term: 'RestClient', def: 'Spring\'s modern synchronous HTTP client that replaces RestTemplate; designed to coexist with WebClient so blocking and reactive styles can be mixed in the same application.' },
  { term: 'RestTemplate', def: 'Spring\'s older synchronous HTTP client, used in blocking controller code; contrasts with WebClient in the traditional-vs-reactive comparison.' },
  { term: 'Server-Sent Events', def: 'A streaming protocol delivered over the text/event-stream MIME type that lets a server push incremental updates to a browser over a single long-lived HTTP connection.' },
  { term: 'Server-Streaming', def: 'A reactive communication pattern in which a single client request triggers a stream of many server responses, one of the four patterns supported by Spring WebFlux.' },
  { term: 'Spring Data R2DBC', def: 'Spring\'s familiar repository abstraction over the R2DBC specification, providing ReactiveCrudRepository, entity mapping, and derived-query support for reactive database access.' },
  { term: 'Spring Initializr', def: 'The project-generation web tool at start.spring.io used to bootstrap a Spring Boot project with chosen dependencies, build tool, and language version.' },
  { term: 'Spring Web MVC', def: 'Spring\'s traditional servlet-based web framework that uses blocking I/O and a single request-response communication model, contrasted with WebFlux throughout the course.' },
  { term: 'Spring WebFlux', def: 'Spring\'s reactive web framework built on Project Reactor, supporting non-blocking I/O, streaming responses, and the four communication patterns (request-response, server-streaming, client-streaming, bidirectional streaming).' },
  { term: 'StepVerifier', def: 'A Project Reactor test utility (reactor.test.StepVerifier) that subscribes to a Mono or Flux and asserts the expected items, terminal signal, and order; the test does not actually run until .verify() is called.' },
  { term: 'Swagger UI', def: 'An auto-generated API documentation interface served by the external product service at localhost:7070, used to explore and test endpoints before writing any client code.' },
  { term: 'WebClient', def: 'Spring\'s non-blocking, reactive HTTP client used as the reactive counterpart to RestClient; returns Mono or Flux from remote calls so cancellation and backpressure can propagate end to end.' },
  { term: 'WebFilter', def: 'A Spring WebFlux component that intercepts HTTP requests and responses in the reactive pipeline, the reactive equivalent of a servlet filter, used for cross-cutting concerns like logging and authentication.' },
]
